const GROUPS = [["ref", "变量与引用"], ["num", "数字与运算"], ["str", "字符串"], ["list", "列表"], ["slice", "切片"], ["dict", "字典"], ["set", "集合与元组"], ["truth", "条件与真值"], ["loop", "循环"], ["comp", "推导式与生成器"], ["func", "函数"], ["cls", "类与对象"], ["exc", "异常"], ["io", "文件、JSON 与路径"], ["std", "标准库"], ["flow", "迭代器、装饰器、上下文"], ["mod", "标注、异步与现代语法"], ["np", "NumPy"], ["pd", "pandas"]];
const CARDS = [{"g":"ref","c":"a = [1, 2]\nb = a\nb.append(3)\nprint(a)","a":"[1, 2, 3]","d":["[1, 2]","[3]"],"w":"b = a 只是多一个名字,指向同一个列表。","id":"ref_44a452"},{"g":"ref","c":"a = [1, 2]\nb = a[:]\nb.append(3)\nprint(a)","a":"[1, 2]","d":["[1, 2, 3]","[3]"],"w":"a[:] 切出一份新列表,改 b 不影响 a。","id":"ref_4536d9"},{"g":"ref","c":"a = 5\nb = a\nb += 1\nprint(a)","a":"5","d":["6","1"],"w":"int 不可变,b += 1 让 b 指向新对象。","id":"ref_feb61c"},{"g":"ref","c":"x = [1, 2]\ny = [1, 2]\nprint(x == y, x is y)","a":"True False","d":["True True","False False"],"w":"== 比内容,is 比是不是同一个对象。","id":"ref_c4d192"},{"g":"ref","c":"a = [[0]] * 3\na[0].append(1)\nprint(a)","a":"[[0, 1], [0, 1], [0, 1]]","d":["[[0, 1], [0], [0]]","[[0], [0], [0], 1]"],"w":"乘出来的三格是同一个内层列表。","id":"ref_4a1dbd"},{"g":"ref","c":"a = [[1], [2]]\nb = a.copy()\nb[0].append(9)\nprint(a)","a":"[[1, 9], [2]]","d":["[[1], [2]]","[[1], [2], 9]"],"w":"copy() 只复制外层,内层列表仍是共用的。","id":"ref_5d4d82"},{"g":"ref","c":"import copy\na = [[1], [2]]\nb = copy.deepcopy(a)\nb[0].append(9)\nprint(a)","a":"[[1], [2]]","d":["[[1, 9], [2]]","[[9], [2]]"],"w":"deepcopy 连内层一起复制。","id":"ref_f4eb9b"},{"g":"ref","c":"a, b = 1, 2\na, b = b, a\nprint(a, b)","a":"2 1","d":["1 2","2 2"],"w":"右边先打包成元组,再一起解包,所以能直接交换。","id":"ref_f57931"},{"g":"ref","c":"def f(x):\n    x.append(1)\nlst = []\nf(lst)\nprint(lst)","a":"[1]","d":["[]","None"],"w":"传进去的是同一个列表,原地修改外面看得见。","id":"ref_eb40b4"},{"g":"ref","c":"def f(x):\n    x = x + [1]\nlst = []\nf(lst)\nprint(lst)","a":"[]","d":["[1]","None"],"w":"x + [1] 造了新列表并只改了函数里的名字。","id":"ref_34eee3"},{"g":"ref","c":"a = [1, 2, 3]\nb = a\na = a + [4]\nprint(b)","a":"[1, 2, 3]","d":["[1, 2, 3, 4]","[4]"],"w":"a + [4] 是新列表;b 还指着旧的。","id":"ref_d26cef"},{"g":"ref","c":"a = [1, 2, 3]\nb = a\na += [4]\nprint(b)","a":"[1, 2, 3, 4]","d":["[1, 2, 3]","[4]"],"w":"列表的 += 是原地扩展,和 a = a + [4] 不同。","id":"ref_c33f09"},{"g":"ref","c":"s = 'abc'\nt = s\nt += 'd'\nprint(s)","a":"abc","d":["abcd","d"],"w":"字符串不可变,+= 生成新串。","id":"ref_729580"},{"g":"ref","c":"x = None\nprint(x is None, x == False)","a":"True False","d":["True True","False False"],"w":"None 不等于 False;判空用 is None。","id":"ref_0246c3"},{"g":"num","c":"print(7 // 2, 7 % 2, 7 / 2)","a":"3 1 3.5","d":["3 1 3","3.5 1 3.5"],"w":"// 整除,% 取余,/ 永远得 float。","id":"num_bd35e9"},{"g":"num","c":"print(-7 // 2)","a":"-4","d":["-3","-3.5"],"w":"整除向下取整(往负无穷),不是向零。","id":"num_a317a1"},{"g":"num","c":"print(2 ** 10, 2 ** 0.5 > 1.41)","a":"1024 True","d":["20 True","1024 False"],"w":"** 是乘方。","id":"num_64ffc5"},{"g":"num","c":"print(0.1 + 0.2 == 0.3)","a":"False","d":["True"],"w":"二进制浮点存不准 0.1;比较用 math.isclose。","id":"num_ccfa18"},{"g":"num","c":"import math\nprint(math.isclose(0.1 + 0.2, 0.3))","a":"True","d":["False"],"w":"浮点比较的正确姿势。","id":"num_54e7cd"},{"g":"num","c":"print(round(2.5), round(3.5))","a":"2 4","d":["3 4","2 3"],"w":"Python 的 round 是\"四舍六入五成双\"。","id":"num_19c94e"},{"g":"num","c":"print(int('42') + 1, str(42) + '1')","a":"43 421","d":["43 43","421 421"],"w":"类型决定 + 是加法还是拼接。","id":"num_7aa62b"},{"g":"num","c":"print(int(3.99), round(3.99))","a":"3 4","d":["4 4","3 3"],"w":"int() 直接截断小数,不四舍五入。","id":"num_214678"},{"g":"num","c":"print(10 / 2)","a":"5.0","d":["5"],"w":"/ 的结果永远是 float。","id":"num_4d65d0"},{"g":"num","c":"print(divmod(17, 5))","a":"(3, 2)","d":["(2, 3)","3.4"],"w":"一次拿到商和余数。","id":"num_73c058"},{"g":"num","c":"print(True + True)","a":"2","d":["True","TypeError"],"w":"bool 是 int 的子类,True 就是 1。","id":"num_783377"},{"g":"num","c":"print(f'{3.14159:.2f}')","a":"3.14","d":["3.1","3.14159"],"w":":.2f 保留两位小数。","id":"num_beb4ba"},{"g":"num","c":"print(f'{1234567:,}')","a":"1,234,567","d":["1234567","1.234.567"],"w":":, 加千分位。","id":"num_a5b93d"},{"g":"num","c":"print(f'{0.256:.1%}')","a":"25.6%","d":["0.3%","25.6"],"w":"% 格式先乘 100 再加百分号。","id":"num_ad6728"},{"g":"num","c":"print(float('inf') > 10 ** 100)","a":"True","d":["False","OverflowError"],"w":"inf 比任何有限数都大。","id":"num_e2ca73"},{"g":"num","c":"print(bool(0), bool(0.0), bool(-1))","a":"False False True","d":["False False False","True True True"],"w":"只有零值是假,负数也是真。","id":"num_910304"},{"g":"num","c":"print(1_000_000 + 1)","a":"1000001","d":["SyntaxError","1_000_001"],"w":"数字里的下划线只是给人看的分隔符。","id":"num_8c55b3"},{"g":"num","c":"print(abs(-3), max(1, 5, 2), sum([1, 2, 3]))","a":"3 5 6","d":["-3 5 6","3 2 6"],"w":"三个最常用的内置函数。","id":"num_9b5105"},{"g":"num","c":"print(int('3.5'))","a":"ValueError","d":["3","4"],"w":"int() 不吃带小数点的字符串;先 float 再 int。","id":"num_41eb2d"},{"g":"num","c":"print(type(1 / 1).__name__, type(1 // 1).__name__)","a":"float int","d":["int int","float float"],"w":"/ 得 float,// 两边都是 int 时得 int。","id":"num_3f82ca"},{"g":"str","c":"print('a,b,,c'.split(','))","a":"['a', 'b', '', 'c']","d":["['a', 'b', 'c']","['a', 'b', None, 'c']"],"w":"指定分隔符时,连续分隔符之间会留空串。","id":"str_b4813e"},{"g":"str","c":"print(' a  b '.split())","a":"['a', 'b']","d":["['', 'a', '', 'b', '']","['a', '', 'b']"],"w":"不带参数的 split 按任意空白切并丢掉空串。","id":"str_f3d12c"},{"g":"str","c":"print('-'.join(['a', 'b', 'c']))","a":"a-b-c","d":["-a-b-c-","abc"],"w":"分隔符.join(列表)。","id":"str_ebd754"},{"g":"str","c":"print('hello'.replace('l', 'L', 1))","a":"heLlo","d":["heLLo","hello"],"w":"第三个参数限制替换次数。","id":"str_ddc892"},{"g":"str","c":"print('abc'[::-1])","a":"cba","d":["abc","c"],"w":"步长 -1 就是反转。","id":"str_041298"},{"g":"str","c":"print('ab' * 3)","a":"ababab","d":["ab3","TypeError"],"w":"字符串乘整数是重复。","id":"str_b1e045"},{"g":"str","c":"print('py' in 'python', 'Py' in 'python')","a":"True False","d":["True True","False False"],"w":"in 找子串,区分大小写。","id":"str_442dff"},{"g":"str","c":"print('abc'.find('z'), 'abc'.find('c'))","a":"-1 2","d":["None 2","ValueError"],"w":"find 找不到返回 -1,不报错。","id":"str_70122b"},{"g":"str","c":"print('abc'.index('z'))","a":"ValueError","d":["-1","None"],"w":"index 找不到会抛错,find 不会。","id":"str_4893e1"},{"g":"str","c":"print(len('你好'), len('你好'.encode('utf-8')))","a":"2 6","d":["2 2","6 6"],"w":"len 数字符;编码成 utf-8 后每个汉字 3 字节。","id":"str_a6f9f5"},{"g":"str","c":"print('3' + '4', 3 + 4)","a":"34 7","d":["7 7","34 34"],"w":"字符串相加是拼接。","id":"str_3bb394"},{"g":"str","c":"print('3' + 4)","a":"TypeError","d":["7","34"],"w":"Python 不会替你把数字转成字符串。","id":"str_61b59b"},{"g":"str","c":"print(r'a\\nb', len(r'a\\nb'))","a":"a\\nb 4","d":["a\\nb 3","a b 3"],"w":"r'' 里反斜杠不转义,\\n 是两个字符。","id":"str_0defd5"},{"g":"str","c":"print('abc'.startswith(('x', 'a')))","a":"True","d":["False","TypeError"],"w":"startswith 可以传元组,任一命中即可。","id":"str_4c0ac3"},{"g":"str","c":"print(f'{7:03d}')","a":"007","d":["7","700"],"w":"03d:宽度 3,不足补零。","id":"str_636584"},{"g":"str","c":"print('a b c'.partition(' '))","a":"('a', ' ', 'b c')","d":["['a', 'b', 'c']","('a', 'b c')"],"w":"partition 只切第一刀,返回三段。","id":"str_f5818a"},{"g":"str","c":"print('a.b.c'.rsplit('.', 1))","a":"['a.b', 'c']","d":["['a', 'b.c']","['a', 'b', 'c']"],"w":"rsplit 从右边切,常用来取扩展名。","id":"str_89fa4d"},{"g":"str","c":"s = 'hello'\nprint(s[1:3], s[-1], s[:2])","a":"el o he","d":["ell o he","el l hel"],"w":"切片含头不含尾;-1 是最后一个。","id":"str_4f5494"},{"g":"str","c":"n = 'Ada'\nprint(f'{n!r} has {len(n)}')","a":"'Ada' has 3","d":["Ada has 3","n has 3"],"w":"!r 用 repr,带引号;花括号里可以写表达式。","id":"str_207993"},{"g":"str","c":"x = 3\nprint(f'{x=}')","a":"x=3","d":["3","x"],"w":"f'{x=}' 同时打印名字和值,调试利器。","id":"str_d320a5"},{"g":"str","c":"print('Hello World'.lower().split())","a":"['hello', 'world']","d":["['Hello', 'World']","hello world"],"w":"字符串方法可以链着调,每步都返回新串。","id":"str_95dfa7"},{"g":"str","c":"print('  x '.strip() + '|', 'xxhixx'.strip('x'))","a":"x| hi","d":["x | hi","x | xxhixx"],"w":"strip 去两端;可指定要去掉的字符。","id":"str_0070ba"},{"g":"str","c":"print('42'.isdigit(), '4.2'.isdigit(), ''.isdigit())","a":"True False False","d":["True True False","True False True"],"w":"isdigit 不认小数点,空串也是 False。","id":"str_5411ca"},{"g":"str","c":"print('a' \u003c 'b', 'B' \u003c 'a', 'apple' \u003c 'b')","a":"True True True","d":["True False True","True False False"],"w":"字符串按码点逐位比,大写字母排在小写前。","id":"str_07267b"},{"g":"list","c":"a = [3, 1, 2]\nb = a.sort()\nprint(b)","a":"None","d":["[1, 2, 3]","[3, 1, 2]"],"w":"sort() 原地排序并返回 None。","id":"list_e30e0d"},{"g":"list","c":"a = [3, 1, 2]\nprint(sorted(a), a)","a":"[1, 2, 3] [3, 1, 2]","d":["[1, 2, 3] [1, 2, 3]","None [1, 2, 3]"],"w":"sorted 返回新列表,不动原来的。","id":"list_84c633"},{"g":"list","c":"a = [1, 2, 3]\na.append([4, 5])\nprint(len(a))","a":"4","d":["5","3"],"w":"append 把整个列表当成一个元素塞进去。","id":"list_41a778"},{"g":"list","c":"a = [1, 2, 3]\na.extend([4, 5])\nprint(len(a))","a":"5","d":["4","3"],"w":"extend 把元素逐个接上。","id":"list_e21533"},{"g":"list","c":"a = [1, 2, 3]\nprint(a.pop(), a)","a":"3 [1, 2]","d":["1 [2, 3]","3 [1, 2, 3]"],"w":"pop 默认弹最后一个并返回它。","id":"list_d76fdb"},{"g":"list","c":"a = [1, 2, 3]\na.insert(0, 9)\nprint(a)","a":"[9, 1, 2, 3]","d":["[1, 2, 3, 9]","[0, 9, 1, 2, 3]"],"w":"insert(位置, 值)。","id":"list_436b5d"},{"g":"list","c":"a = [1, 2, 2, 3]\na.remove(2)\nprint(a)","a":"[1, 2, 3]","d":["[1, 3]","[1, 2, 2]"],"w":"remove 只删第一个匹配的。","id":"list_fd735b"},{"g":"list","c":"print([1, 2] + [3], [0] * 3)","a":"[1, 2, 3] [0, 0, 0]","d":["[1, 2, 3] [0, 3]","[4, 2] [0]"],"w":"列表 + 是拼接,* 是重复。","id":"list_ea6c4d"},{"g":"list","c":"a = [1, 2, 3]\nprint(a[5])","a":"IndexError","d":["None","3"],"w":"下标越界直接报错。","id":"list_1224c4"},{"g":"list","c":"a = [1, 2, 3]\nprint(a[1:5])","a":"[2, 3]","d":["IndexError","[2, 3, None, None]"],"w":"切片越界不报错,有多少给多少。","id":"list_a5b061"},{"g":"list","c":"print(sorted(['b', 'A', 'c']))","a":"['A', 'b', 'c']","d":["['b', 'A', 'c']","['A', 'c', 'b']"],"w":"默认按码点,大写排前;要忽略大小写用 key=str.lower。","id":"list_e97a13"},{"g":"list","c":"print(sorted(['bb', 'a', 'ccc'], key=len, reverse=True))","a":"['ccc', 'bb', 'a']","d":["['a', 'bb', 'ccc']","['ccc', 'a', 'bb']"],"w":"key 决定按什么排,reverse 倒序。","id":"list_5d152c"},{"g":"list","c":"a = [1, 2, 3]\nprint(a.index(2), 5 in a)","a":"1 False","d":["2 False","1 True"],"w":"index 给位置,in 判断在不在。","id":"list_0fcc34"},{"g":"list","c":"a = [1, 2, 3]\ndel a[0]\nprint(a)","a":"[2, 3]","d":["[1, 2]","[0, 2, 3]"],"w":"del 按位置删。","id":"list_2dd92f"},{"g":"list","c":"a = [1, 2, 3]\na[1:2] = [8, 9]\nprint(a)","a":"[1, 8, 9, 3]","d":["[1, [8, 9], 3]","[1, 8, 9]"],"w":"给切片赋值可以改变长度。","id":"list_833548"},{"g":"list","c":"m = [[1, 2], [3, 4]]\nprint(m[1][0], [r[0] for r in m])","a":"3 [1, 3]","d":["2 [1, 2]","3 [1, 2]"],"w":"先行后列;取一列用推导式。","id":"list_a24dbf"},{"g":"list","c":"a = [1, 2, 3]\nfor x in a:\n    x *= 2\nprint(a)","a":"[1, 2, 3]","d":["[2, 4, 6]","[1, 2, 3, 2, 4, 6]"],"w":"循环变量只是个名字,改它不改列表。","id":"list_f110e6"},{"g":"list","c":"a = [1, 2, 3]\nfor i in range(len(a)):\n    a[i] *= 2\nprint(a)","a":"[2, 4, 6]","d":["[1, 2, 3]","[2, 2, 2]"],"w":"按下标赋值才是真的改列表。","id":"list_0ec3eb"},{"g":"list","c":"a = [1, 2, 3, 4]\nfor x in a:\n    if x % 2 == 0:\n        a.remove(x)\nprint(a)","a":"[1, 3]","d":["[1, 2, 3]","[1, 3, 4]"],"w":"这次碰巧对了;边遍历边删会跳元素,别依赖它。","id":"list_a0bb07"},{"g":"list","c":"a = [2, 4, 5]\nfor x in a:\n    if x % 2 == 0:\n        a.remove(x)\nprint(a)","a":"[4, 5]","d":["[5]","[2, 5]"],"w":"删掉 2 后 4 滑到位置 0,被游标跳过。","id":"list_2dae6d"},{"g":"list","c":"print(list(reversed([1, 2, 3])), [4, 2, 8].count(2))","a":"[3, 2, 1] 1","d":["[1, 2, 3] 1","[3, 2, 1] 2"],"w":"reversed 给迭代器,要 list() 才看得见。","id":"list_4db95b"},{"g":"slice","c":"print('python'[::2])","a":"pto","d":["pyt","yhn"],"w":"步长 2:每隔一个取一个。","id":"slice_a50fa4"},{"g":"slice","c":"a = [0, 1, 2, 3, 4]\nprint(a[-2:])","a":"[3, 4]","d":["[4]","[0, 1, 2]"],"w":"负数从尾部数;-2: 是最后两个。","id":"slice_3a1684"},{"g":"slice","c":"a = [0, 1, 2, 3, 4]\nprint(a[:-1])","a":"[0, 1, 2, 3]","d":["[4]","[0, 1, 2, 3, 4]"],"w":":-1 去掉最后一个。","id":"slice_296917"},{"g":"slice","c":"a = [0, 1, 2, 3, 4]\nprint(a[1:4:2])","a":"[1, 3]","d":["[1, 2, 3]","[1, 3, 4]"],"w":"起:止:步,止不含。","id":"slice_a7aa37"},{"g":"slice","c":"a = [0, 1, 2, 3, 4]\nprint(a[10:], a[::-2])","a":"[] [4, 2, 0]","d":["IndexError","[] [4, 3]"],"w":"越界切片给空列表;负步长倒着走。","id":"slice_a86dbf"},{"g":"slice","c":"a = [0, 1, 2, 3, 4]\na[:2] = []\nprint(a)","a":"[2, 3, 4]","d":["[[], 2, 3, 4]","[0, 1, 2, 3, 4]"],"w":"把切片赋成空就是删除这一段。","id":"slice_af5892"},{"g":"slice","c":"s = '2026-11-10'\nprint(s[:4], s[5:7])","a":"2026 11","d":["2026 -1","2026 11-"],"w":"定长字符串用切片取字段最直接。","id":"slice_7161b4"},{"g":"slice","c":"a = [0, 1, 2]\nb = a[:]\nprint(b is a, b == a)","a":"False True","d":["True True","False False"],"w":"整段切片是浅拷贝。","id":"slice_2eeb76"},{"g":"slice","c":"print('abcdef'[-3:-1])","a":"de","d":["def","ed"],"w":"-3 到 -1,不含 -1。","id":"slice_c7e28d"},{"g":"slice","c":"a = [0, 1, 2, 3, 4, 5]\nprint(a[::3], a[1::3])","a":"[0, 3] [1, 4]","d":["[0, 3] [1, 4, 5]","[0, 1, 2] [1, 2, 3]"],"w":"分片取样:从哪开始,每隔几个。","id":"slice_5d2785"},{"g":"dict","c":"d = {'a': 1}\nprint(d.get('b'), d.get('b', 0))","a":"None 0","d":["KeyError","0 0"],"w":"get 取不到给 None 或你指定的默认值。","id":"dict_62d33d"},{"g":"dict","c":"d = {'a': 1}\nprint(d['b'])","a":"KeyError","d":["None","0"],"w":"方括号取不存在的键会抛错。","id":"dict_a7f03f"},{"g":"dict","c":"d = {'a': 1, 'b': 2}\nprint(list(d))","a":"['a', 'b']","d":["[1, 2]","[('a', 1), ('b', 2)]"],"w":"遍历字典得到的是键,且保持插入顺序。","id":"dict_acb180"},{"g":"dict","c":"d = {'a': 1, 'b': 2}\nprint([k + str(v) for k, v in d.items()])","a":"['a1', 'b2']","d":["['a', 'b']","[('a', 1), ('b', 2)]"],"w":"items() 同时给键和值。","id":"dict_d82dd5"},{"g":"dict","c":"d = {}\nd.setdefault('x', []).append(1)\nprint(d)","a":"{'x': [1]}","d":["{}","{'x': []}"],"w":"setdefault:没有就建,然后返回那个值。","id":"dict_0a74e7"},{"g":"dict","c":"d = {'a': 1}\nd.update({'a': 2, 'b': 3})\nprint(d)","a":"{'a': 2, 'b': 3}","d":["{'a': 1, 'b': 3}","{'a': 1}"],"w":"update 里同名键以后来的为准。","id":"dict_ba42a3"},{"g":"dict","c":"a = {'x': 1}\nb = {'x': 2, 'y': 3}\nprint(a | b)","a":"{'x': 2, 'y': 3}","d":["{'x': 1, 'y': 3}","TypeError"],"w":"| 合并字典,右边覆盖左边。","id":"dict_732a75"},{"g":"dict","c":"d = {'a': 1}\nprint('a' in d, 1 in d)","a":"True False","d":["True True","False True"],"w":"in 只查键,不查值。","id":"dict_a022e5"},{"g":"dict","c":"d = {'b': 2, 'a': 1}\nprint(sorted(d), max(d, key=d.get))","a":"['a', 'b'] b","d":["['b', 'a'] b","['a', 'b'] a"],"w":"max(d, key=d.get):值最大的那个键。","id":"dict_6c9d42"},{"g":"dict","c":"d = {'a': 1}\nprint(d.pop('a'), d)","a":"1 {}","d":["a {}","1 {'a': 1}"],"w":"pop 取走并删除。","id":"dict_5eae24"},{"g":"dict","c":"d = {[1, 2]: 'x'}","a":"TypeError","d":["KeyError","正常运行"],"w":"列表可变、不可哈希,不能当键。","id":"dict_52a5a2"},{"g":"dict","c":"d = {(1, 2): 'x'}\nprint(d[(1, 2)])","a":"x","d":["TypeError","KeyError"],"w":"元组不可变,可以当键。","id":"dict_9bedc1"},{"g":"dict","c":"print({k: v for k, v in zip('ab', [1, 2])})","a":"{'a': 1, 'b': 2}","d":["{'ab': [1, 2]}","[('a', 1), ('b', 2)]"],"w":"zip 配对后用字典推导式。","id":"dict_268577"},{"g":"dict","c":"d = {'a': {'b': 1}}\nprint(d.get('z', {}).get('b'))","a":"None","d":["KeyError","1"],"w":"链式 get 给个空字典兜底,嵌套取值不炸。","id":"dict_705212"},{"g":"dict","c":"print(len({'a': 1, 'a': 2}))","a":"1","d":["2","SyntaxError"],"w":"重复的键后者覆盖前者。","id":"dict_ec50f5"},{"g":"dict","c":"d = {'a': 1, 'b': 2}\nprint({v: k for k, v in d.items()})","a":"{1: 'a', 2: 'b'}","d":["{'a': 1, 'b': 2}","{1: 'b', 2: 'a'}"],"w":"反转键值的惯用写法。","id":"dict_341ccb"},{"g":"dict","c":"from collections import Counter\nprint(Counter('aab').most_common(1))","a":"[('a', 2)]","d":["('a', 2)","{'a': 2}"],"w":"Counter 计数,most_common 给排行榜。","id":"dict_b83d7c"},{"g":"dict","c":"from collections import defaultdict\nd = defaultdict(int)\nd['x'] += 1\nprint(d['x'], d['y'])","a":"1 0","d":["1 KeyError","1 None"],"w":"defaultdict 取不存在的键时自动用工厂造一个。","id":"dict_30ca0e"},{"g":"dict","c":"d = {'a': 1, 'b': 2}\nfor k in d:\n    del d[k]","a":"RuntimeError","d":["正常运行","KeyError"],"w":"遍历字典时不能改它的大小;先 list(d) 再删。","id":"dict_07fd5e"},{"g":"dict","c":"d = dict(a=1)\nd['a'] += 1\nd['b'] = d.get('b', 0) + 1\nprint(d)","a":"{'a': 2, 'b': 1}","d":["{'a': 2}","KeyError"],"w":"get(k, 0) + 1 是不用 defaultdict 时的计数写法。","id":"dict_4e5778"},{"g":"set","c":"print(len({1, 2, 2, 3}))","a":"3","d":["4","2"],"w":"集合自动去重。","id":"set_951f8c"},{"g":"set","c":"print({1, 2} & {2, 3}, {1, 2} | {2, 3})","a":"{2} {1, 2, 3}","d":["{1, 2, 3} {2}","{2} {1, 2, 2, 3}"],"w":"& 交集,| 并集。","id":"set_f71178"},{"g":"set","c":"print({1, 2, 3} - {2}, {1, 2} ^ {2, 3})","a":"{1, 3} {1, 3}","d":["{1, 3} {2}","{2} {1, 3}"],"w":"- 差集;^ 对称差(只在一边的)。","id":"set_ba8f04"},{"g":"set","c":"print(type({}).__name__, type(set()).__name__)","a":"dict set","d":["set set","dict dict"],"w":"{} 是空字典;空集合只能写 set()。","id":"set_410580"},{"g":"set","c":"t = (1, 2)\nt[0] = 9","a":"TypeError","d":["(9, 2)","IndexError"],"w":"元组不可变。","id":"set_d00b05"},{"g":"set","c":"t = (1)\nprint(type(t).__name__, type((1,)).__name__)","a":"int tuple","d":["tuple tuple","int int"],"w":"单元素元组必须带逗号。","id":"set_77a263"},{"g":"set","c":"t = ([1], 2)\nt[0].append(3)\nprint(t)","a":"([1, 3], 2)","d":["TypeError","([1], 2)"],"w":"元组不可变,但里面装的列表照样能改。","id":"set_41c5d0"},{"g":"set","c":"a, *b = [1, 2, 3]\nprint(a, b)","a":"1 [2, 3]","d":["1 2","[1] [2, 3]"],"w":"星号解包接住剩下的。","id":"set_edcc8a"},{"g":"set","c":"print(sorted(set('banana')))","a":"['a', 'b', 'n']","d":["['b', 'a', 'n']","['a', 'a', 'a', 'b', 'n', 'n']"],"w":"去重再排序。","id":"set_f74e51"},{"g":"set","c":"print(list(dict.fromkeys([3, 1, 3, 2, 1])))","a":"[3, 1, 2]","d":["[1, 2, 3]","[3, 1, 3, 2, 1]"],"w":"保持原顺序去重的惯用写法。","id":"set_897469"},{"g":"set","c":"x = 1, 2\nprint(x)","a":"(1, 2)","d":["1 2","[1, 2]"],"w":"逗号才是造元组的,括号可有可无。","id":"set_b512b0"},{"g":"set","c":"s = {1}\ns.add(1)\ns.add(2)\nprint(len(s))","a":"2","d":["3","1"],"w":"重复 add 没有效果。","id":"set_322201"},{"g":"set","c":"print((1, 2) \u003c (1, 3), (2,) \u003c (1, 9))","a":"True False","d":["True True","False False"],"w":"元组逐位比较,先比第一位。","id":"set_cd78c1"},{"g":"set","c":"print({1, 2} \u003c= {1, 2, 3}, 3 in {1, 2})","a":"True False","d":["False False","True True"],"w":"\u003c= 判子集。","id":"set_377953"},{"g":"set","c":"s = {[1, 2]}","a":"TypeError","d":["{[1, 2]}","ValueError"],"w":"集合元素必须可哈希,列表不行。","id":"set_14b9c2"},{"g":"truth","c":"print(bool([]), bool([0]), bool(''))","a":"False True False","d":["False False False","True True False"],"w":"空容器为假;[0] 不空,所以是真。","id":"truth_c3f25b"},{"g":"truth","c":"print(1 \u003c 2 \u003c 3, 3 > 2 > 2)","a":"True False","d":["True True","False False"],"w":"比较可以连写,等价于用 and 连接。","id":"truth_75e255"},{"g":"truth","c":"print(0 or 'x', 1 and 'y')","a":"x y","d":["True True","0 1"],"w":"or/and 返回的是操作数本身,不是 True/False。","id":"truth_e1b4e3"},{"g":"truth","c":"print(None or 0 or [])","a":"[]","d":["None","False"],"w":"全是假值时,or 返回最后一个。","id":"truth_026a40"},{"g":"truth","c":"x = 0\ny = x or 10\nprint(y)","a":"10","d":["0","True"],"w":"用 or 给默认值会把合法的 0 也替换掉。","id":"truth_1e1969"},{"g":"truth","c":"x = 5\nprint('big' if x > 3 else 'small')","a":"big","d":["small","True"],"w":"条件表达式:A if 条件 else B。","id":"truth_0444de"},{"g":"truth","c":"print(not None, not 'a')","a":"True False","d":["False False","True True"],"w":"not 总是返回 bool。","id":"truth_a86521"},{"g":"truth","c":"print(1 == 1.0, '1' == 1)","a":"True False","d":["True True","False False"],"w":"数值跨类型可以相等;字符串和数字永不相等。","id":"truth_2dc947"},{"g":"truth","c":"print(any([0, '', 3]), all([1, 0]))","a":"True False","d":["False False","True True"],"w":"any 有一个真就真;all 要全真。","id":"truth_c11823"},{"g":"truth","c":"print(all([]), any([]))","a":"True False","d":["False False","True True"],"w":"空的 all 是 True——\"没有反例\"。","id":"truth_bbc31e"},{"g":"truth","c":"x = 404\nmatch x:\n    case 200:\n        r = 'ok'\n    case 404:\n        r = 'nf'\n    case _:\n        r = '?'\nprint(r)","a":"nf","d":["?","ok"],"w":"match/case 逐个比对,_ 是兜底。","id":"truth_d2327d"},{"g":"truth","c":"if (n := len('abc')) > 2:\n    print(n)","a":"3","d":["True","abc"],"w":":= 在表达式里顺手赋值。","id":"truth_66cb2d"},{"g":"truth","c":"print(None == False, bool(None))","a":"False False","d":["True False","False True"],"w":"None 是假值,但不等于 False。","id":"truth_53c3d2"},{"g":"truth","c":"print(3 if None else 4, [] or 'empty')","a":"4 empty","d":["3 []","4 []"],"w":"假值走 else / or 的右边。","id":"truth_eb1451"},{"g":"truth","c":"x = []\nif x is not None:\n    print('A')\nif x:\n    print('B')","a":"A","d":["A ⏎ B","B"],"w":"空列表不是 None,但它是假值。","id":"truth_98bf28"},{"g":"truth","c":"print(isinstance(True, int), True == 1)","a":"True True","d":["False True","False False"],"w":"bool 是 int 的子类。","id":"truth_bd97ac"},{"g":"loop","c":"print(list(range(3)), list(range(1, 4)))","a":"[0, 1, 2] [1, 2, 3]","d":["[1, 2, 3] [1, 2, 3, 4]","[0, 1, 2, 3] [1, 2, 3]"],"w":"range 含头不含尾。","id":"loop_dd7897"},{"g":"loop","c":"print(list(range(10, 0, -3)))","a":"[10, 7, 4, 1]","d":["[10, 7, 4]","[10, 7, 4, 1, -2]"],"w":"第三个参数是步长,可以为负。","id":"loop_9f3db9"},{"g":"loop","c":"print(list(enumerate('ab', 1)))","a":"[(1, 'a'), (2, 'b')]","d":["[(0, 'a'), (1, 'b')]","[('a', 1), ('b', 2)]"],"w":"enumerate 给(序号, 元素),可指定起始。","id":"loop_ab83b7"},{"g":"loop","c":"print(list(zip([1, 2, 3], 'ab')))","a":"[(1, 'a'), (2, 'b')]","d":["[(1, 'a'), (2, 'b'), (3, None)]","ValueError"],"w":"zip 以最短的为准,多出来的悄悄丢掉。","id":"loop_f7535a"},{"g":"loop","c":"for i in range(3):\n    if i == 5:\n        break\nelse:\n    print('no break')","a":"no break","d":["什么都不输出","SyntaxError"],"w":"for 的 else:循环没被 break 才执行。","id":"loop_d459af"},{"g":"loop","c":"total = 0\nfor i in range(5):\n    if i % 2:\n        continue\n    total += i\nprint(total)","a":"6","d":["4","10"],"w":"continue 跳过奇数,加的是 0+2+4。","id":"loop_bb3b49"},{"g":"loop","c":"for i in range(3):\n    pass\nprint(i)","a":"2","d":["3","NameError"],"w":"循环变量在循环结束后还活着,停在最后一个值。","id":"loop_b3703f"},{"g":"loop","c":"n = 0\nfor i in range(3):\n    for j in range(3):\n        if j == 1:\n            break\n        n += 1\nprint(n)","a":"3","d":["1","9"],"w":"break 只跳出最里面那层。","id":"loop_d629ba"},{"g":"loop","c":"print(sum(i * i for i in range(4)))","a":"14","d":["9","30"],"w":"0+1+4+9;生成器表达式直接喂给 sum。","id":"loop_17a7fc"},{"g":"loop","c":"print(list(zip(*[(1, 'a'), (2, 'b')])))","a":"[(1, 2), ('a', 'b')]","d":["[(1, 'a'), (2, 'b')]","[1, 2, 'a', 'b']"],"w":"zip(*行) 把行转成列。","id":"loop_d28786"},{"g":"loop","c":"it = iter([1, 2])\nnext(it)\nprint(list(it))","a":"[2]","d":["[1, 2]","[]"],"w":"迭代器只往前走,走过的不回来。","id":"loop_292dd4"},{"g":"loop","c":"i = 0\nwhile i \u003c 3:\n    i += 1\nprint(i)","a":"3","d":["2","4"],"w":"条件不成立时才退出,此时 i 已经是 3。","id":"loop_e66b4f"},{"g":"loop","c":"d = {'a': 1, 'b': 2}\nfor k, v in sorted(d.items(), key=lambda kv: -kv[1]):\n    print(k, end=' ')","a":"b a","d":["a b","2 1"],"w":"按值倒序遍历字典。","id":"loop_118b71"},{"g":"loop","c":"print(len(range(5, 5)), list(range(0)))","a":"0 []","d":["1 [0]","5 []"],"w":"空 range 不报错,循环一次也不跑。","id":"loop_5dd162"},{"g":"loop","c":"names = ['a', 'b']\nfor i, n in enumerate(names):\n    names[i] = n.upper()\nprint(names)","a":"['A', 'B']","d":["['a', 'b']","['A', 'b']"],"w":"要改列表,用 enumerate 拿下标。","id":"loop_cc2c8b"},{"g":"comp","c":"print([x * 2 for x in range(3)])","a":"[0, 2, 4]","d":["[2, 4, 6]","[0, 1, 2, 0, 1, 2]"],"w":"[表达式 for 变量 in 可迭代]。","id":"comp_a9794c"},{"g":"comp","c":"print([x for x in range(6) if x % 2])","a":"[1, 3, 5]","d":["[0, 2, 4]","[1, 1, 1]"],"w":"末尾的 if 是过滤;x % 2 为真即奇数。","id":"comp_3d6d3e"},{"g":"comp","c":"print([x if x > 1 else 0 for x in range(4)])","a":"[0, 0, 2, 3]","d":["[2, 3]","[0, 1, 2, 3]"],"w":"前面的 if/else 是取值,不过滤。","id":"comp_24e9b2"},{"g":"comp","c":"print({x % 2 for x in range(5)})","a":"{0, 1}","d":["[0, 1, 0, 1, 0]","{0, 1, 0, 1, 0}"],"w":"花括号是集合推导式,自动去重。","id":"comp_34c7d7"},{"g":"comp","c":"print([(a, b) for a in 'xy' for b in (1, 2)][1])","a":"('x', 2)","d":["('y', 1)","('x', 1)"],"w":"多个 for 从左到右嵌套,右边转得快。","id":"comp_00b4bd"},{"g":"comp","c":"g = (x for x in range(3))\nprint(sum(g), sum(g))","a":"3 0","d":["3 3","0 0"],"w":"生成器只能走一遍,第二次已经空了。","id":"comp_c6c6cf"},{"g":"comp","c":"print(type((x for x in [])).__name__, type([x for x in []]).__name__)","a":"generator list","d":["tuple list","list list"],"w":"圆括号得到的是生成器,不是元组。","id":"comp_77dbca"},{"g":"comp","c":"m = [[1, 2], [3, 4]]\nprint([x for r in m for x in r])","a":"[1, 2, 3, 4]","d":["[[1, 2], [3, 4]]","[1, 3, 2, 4]"],"w":"拍平二维列表。","id":"comp_2d85a5"},{"g":"comp","c":"print(list(map(str, [1, 2])), list(filter(None, [0, 1, '', 2])))","a":"['1', '2'] [1, 2]","d":["[1, 2] [1, 2]","['1', '2'] [0, 1, '', 2]"],"w":"filter(None, ...) 留下真值。","id":"comp_c6ff48"},{"g":"comp","c":"print(max(len(w) for w in ['aa', 'b', 'cccc']))","a":"4","d":["cccc","3"],"w":"取的是长度的最大值;要词本身用 max(words, key=len)。","id":"comp_901dd1"},{"g":"comp","c":"x = 10\nr = [x for x in range(3)]\nprint(x)","a":"10","d":["2","3"],"w":"推导式有自己的作用域,不污染外面的 x。","id":"comp_a5b4f3"},{"g":"comp","c":"print({w: len(w) for w in ['hi', 'yo'] if w != 'yo'})","a":"{'hi': 2}","d":["{'hi': 2, 'yo': 2}","['hi']"],"w":"字典推导式同样可以带过滤。","id":"comp_545bb8"},{"g":"comp","c":"sq = [n * n for n in range(1, 6)]\nprint(sq[-1], sum(sq))","a":"25 55","d":["36 91","25 30"],"w":"range(1, 6) 是 1 到 5。","id":"comp_a8aeaf"},{"g":"comp","c":"words = ['a', 'bb', 'a']\nprint(len(words), len(set(words)), len([w for w in words if w == 'a']))","a":"3 2 2","d":["3 2 1","3 3 2"],"w":"三种数法:总数、去重数、条件计数。","id":"comp_f0acce"},{"g":"func","c":"def f(a, b=2):\n    return a + b\nprint(f(1), f(1, b=5))","a":"3 6","d":["3 3","1 6"],"w":"默认参数可以被关键字覆盖。","id":"func_aee4a6"},{"g":"func","c":"def f():\n    pass\nprint(f())","a":"None","d":["什么都不输出","NameError"],"w":"没有 return 的函数返回 None。","id":"func_e37409"},{"g":"func","c":"def f(x, acc=[]):\n    acc.append(x)\n    return acc\nf(1)\nprint(f(2))","a":"[1, 2]","d":["[2]","[1]"],"w":"默认值只在定义时创建一次,可变默认值会跨调用累积。","id":"func_16c5c9"},{"g":"func","c":"def f(x, acc=None):\n    acc = acc or []\n    acc.append(x)\n    return acc\nf(1)\nprint(f(2))","a":"[2]","d":["[1, 2]","None"],"w":"可变默认值的正确写法:None 作哨兵。","id":"func_bd21c5"},{"g":"func","c":"def f(*args, **kw):\n    return len(args), sorted(kw)\nprint(f(1, 2, a=3))","a":"(2, ['a'])","d":["(3, [])","(2, [3])"],"w":"*args 收位置参数,**kw 收关键字参数。","id":"func_73cacb"},{"g":"func","c":"def f(a, b):\n    return a - b\nprint(f(b=1, a=5), f(*[5, 1]), f(**{'a': 5, 'b': 1}))","a":"4 4 4","d":["-4 4 4","4 4 -4"],"w":"关键字、* 解列表、** 解字典,三种传法等价。","id":"func_924602"},{"g":"func","c":"x = 1\ndef f():\n    x = 2\nf()\nprint(x)","a":"1","d":["2","None"],"w":"函数里赋值造的是局部变量。","id":"func_458a40"},{"g":"func","c":"x = 1\ndef f():\n    global x\n    x = 2\nf()\nprint(x)","a":"2","d":["1","NameError"],"w":"global 声明后才改得到模块级变量。","id":"func_2bbd2c"},{"g":"func","c":"x = 1\ndef f():\n    print(x)\n    x = 2\nf()","a":"UnboundLocalError","d":["1","2"],"w":"函数里只要有赋值,x 整个函数内都算局部;先读就炸。","id":"func_c84664"},{"g":"func","c":"fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])","a":"[2, 2, 2]","d":["[0, 1, 2]","[0, 0, 0]"],"w":"闭包记的是变量不是值;调用时 i 已经是 2。","id":"func_dac4e1"},{"g":"func","c":"fs = [lambda i=i: i for i in range(3)]\nprint([f() for f in fs])","a":"[0, 1, 2]","d":["[2, 2, 2]","TypeError"],"w":"用默认参数把当时的值钉住。","id":"func_a3983b"},{"g":"func","c":"def f():\n    return 1, 2\na, b = f()\nprint(type(f()).__name__, b)","a":"tuple 2","d":["list 2","int 2"],"w":"\"返回多个值\"其实是返回一个元组。","id":"func_9b84c8"},{"g":"func","c":"print((lambda x, y: x * y)(3, 4))","a":"12","d":["7","(3, 4)"],"w":"lambda 是没有名字的小函数。","id":"func_f6209b"},{"g":"func","c":"def f(a, /, b, *, c):\n    return a + b + c\nprint(f(1, 2, c=3))","a":"6","d":["TypeError","3"],"w":"/ 之前只能按位置,* 之后只能按关键字。","id":"func_4f4a5b"},{"g":"func","c":"def f(a, /, b, *, c):\n    return a + b + c\nprint(f(1, 2, 3))","a":"TypeError","d":["6","3"],"w":"c 在 * 之后,必须写 c=3。","id":"func_f8983f"},{"g":"func","c":"def outer():\n    n = 0\n    def inc():\n        nonlocal n\n        n += 1\n        return n\n    return inc\nc = outer()\nc()\nprint(c())","a":"2","d":["1","UnboundLocalError"],"w":"闭包记住了 n;nonlocal 让内层能改它。","id":"func_5ac4da"},{"g":"func","c":"def f(n):\n    return 1 if n \u003c= 1 else n * f(n - 1)\nprint(f(5))","a":"120","d":["15","24"],"w":"递归:5×4×3×2×1。","id":"func_0a376a"},{"g":"func","c":"def f(a, b):\n    return a\nf(1)","a":"TypeError","d":["1","None"],"w":"少传必填参数直接报错。","id":"func_3c09d7"},{"g":"func","c":"def f(x: int) -> str:\n    return x\nprint(f(5))","a":"5","d":["'5'","TypeError"],"w":"类型标注只是注释,运行时不检查也不转换。","id":"func_7d354f"},{"g":"func","c":"print(sorted([(1, 'b'), (2, 'a')], key=lambda t: t[1]))","a":"[(2, 'a'), (1, 'b')]","d":["[(1, 'b'), (2, 'a')]","['a', 'b']"],"w":"key 函数决定比较什么。","id":"func_c8e346"},{"g":"func","c":"def f(x):\n    return x * 2\ng = f\nprint(g(3), g.__name__)","a":"6 f","d":["6 g","TypeError"],"w":"函数是对象,可以赋给别的名字、当参数传。","id":"func_0e47b2"},{"g":"func","c":"def f():\n    return\n    print('never')\nprint(f())","a":"None","d":["never","never ⏎ None"],"w":"return 之后的代码不会执行。","id":"func_9ad640"},{"g":"cls","c":"class A:\n    def __init__(self, x):\n        self.x = x\na = A(3)\nprint(a.x)","a":"3","d":["None","AttributeError"],"w":"__init__ 在创建实例时自动调用。","id":"cls_07a39a"},{"g":"cls","c":"class A:\n    n = 0\na = A()\nb = A()\na.n = 5\nprint(b.n, A.n)","a":"0 0","d":["5 5","5 0"],"w":"给实例赋值是在实例上新建属性,不动类属性。","id":"cls_1e869a"},{"g":"cls","c":"class A:\n    items = []\na = A()\nb = A()\na.items.append(1)\nprint(b.items)","a":"[1]","d":["[]","AttributeError"],"w":"类属性里的可变对象被所有实例共用。","id":"cls_3cfc4b"},{"g":"cls","c":"class A:\n    def __repr__(self):\n        return 'A!'\nprint([A()])","a":"[A!]","d":["['A!']","[\u003cA object>]"],"w":"__repr__ 决定对象在容器里、调试时怎么显示。","id":"cls_4fa6dd"},{"g":"cls","c":"class A:\n    def hi(self):\n        return 'A'\nclass B(A):\n    def hi(self):\n        return 'B' + super().hi()\nprint(B().hi())","a":"BA","d":["B","AB"],"w":"super() 调父类的同名方法。","id":"cls_e2d87d"},{"g":"cls","c":"from dataclasses import dataclass\n@dataclass\nclass P:\n    x: int\n    y: int = 0\nprint(P(1))","a":"P(x=1, y=0)","d":["\u003cP object>","(1, 0)"],"w":"dataclass 自动生成 __init__ 和 __repr__。","id":"cls_075811"},{"g":"cls","c":"from dataclasses import dataclass\n@dataclass\nclass P:\n    x: int\nprint(P(1) == P(1))","a":"True","d":["False"],"w":"dataclass 还自动生成按字段比较的 __eq__。","id":"cls_acfc9f"},{"g":"cls","c":"class A:\n    pass\nprint(A() == A())","a":"False","d":["True"],"w":"普通类默认按身份比较,两个实例永不相等。","id":"cls_11397d"},{"g":"cls","c":"class A:\n    def f():\n        return 1\nA().f()","a":"TypeError","d":["1","None"],"w":"实例方法第一个参数要留给 self。","id":"cls_de1fec"},{"g":"cls","c":"class A:\n    pass\nclass B(A):\n    pass\nprint(isinstance(B(), A), type(B()) is A)","a":"True False","d":["True True","False False"],"w":"isinstance 认继承关系,type 只认本类。","id":"cls_368525"},{"g":"cls","c":"class C:\n    def __init__(self):\n        self._v = 2\n    @property\n    def v(self):\n        return self._v * 10\nprint(C().v)","a":"20","d":["2","TypeError"],"w":"property 让方法像属性一样读,不用加括号。","id":"cls_a6a458"},{"g":"cls","c":"class Bag:\n    def __init__(self, n):\n        self.n = n\n    def __len__(self):\n        return self.n\nprint(len(Bag(4)), bool(Bag(0)))","a":"4 False","d":["4 True","TypeError"],"w":"定义了 __len__,长度为 0 的对象就是假值。","id":"cls_4e0abb"},{"g":"cls","c":"class A:\n    @classmethod\n    def make(cls):\n        return cls.__name__\nclass B(A):\n    pass\nprint(B.make())","a":"B","d":["A","make"],"w":"classmethod 的 cls 是实际调用它的那个类。","id":"cls_b93ee0"},{"g":"cls","c":"class A:\n    pass\na = A()\na.y = 1\nprint(hasattr(a, 'y'), getattr(a, 'z', 0))","a":"True 0","d":["True AttributeError","False 0"],"w":"属性可以动态加;getattr 带默认值不会炸。","id":"cls_0e3299"},{"g":"cls","c":"class A:\n    pass\nprint(A().x)","a":"AttributeError","d":["None","NameError"],"w":"访问不存在的属性。","id":"cls_c69e7c"},{"g":"cls","c":"from enum import Enum\nclass C(Enum):\n    R = 1\nprint(C.R.name, C(1) is C.R)","a":"R True","d":["1 True","R False"],"w":"枚举成员是单例,可按值查回成员。","id":"cls_da9061"},{"g":"cls","c":"from dataclasses import dataclass\n@dataclass(frozen=True)\nclass P:\n    x: int\np = P(1)\np.x = 2","a":"FrozenInstanceError","d":["正常运行","TypeError"],"w":"frozen=True 让实例不可改,可以当字典键。","id":"cls_7f8093"},{"g":"cls","c":"class A:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, o):\n        return self.x == o.x\nprint(A(1) == A(1), A(1) is A(1))","a":"True False","d":["True True","False False"],"w":"自定义 __eq__ 改的是 ==,is 永远比身份。","id":"cls_0133fc"},{"g":"cls","c":"from typing import NamedTuple\nclass P(NamedTuple):\n    x: int\n    y: int\np = P(1, 2)\nprint(p.x, p[1], p)","a":"1 2 P(x=1, y=2)","d":["1 2 (1, 2)","AttributeError"],"w":"NamedTuple 既能按名字取,也能按下标取。","id":"cls_9aa97d"},{"g":"exc","c":"try:\n    int('x')\nexcept ValueError:\n    print('bad')","a":"bad","d":["ValueError","什么都不输出"],"w":"捕获后程序继续跑。","id":"exc_115cf6"},{"g":"exc","c":"try:\n    x = 1\nexcept Exception:\n    print('e', end=' ')\nelse:\n    print('else', end=' ')\nfinally:\n    print('fin')","a":"else fin","d":["fin","e fin"],"w":"没出错走 else;finally 无论如何都走。","id":"exc_dad8fb"},{"g":"exc","c":"def f():\n    try:\n        return 1\n    finally:\n        print('F', end=' ')\nprint(f())","a":"F 1","d":["1","1 F"],"w":"return 之前 finally 先执行。","id":"exc_e18d92"},{"g":"exc","c":"def f():\n    try:\n        return 'try'\n    finally:\n        return 'fin'\nprint(f())","a":"fin","d":["try","try fin"],"w":"finally 里的 return 会盖掉前面的;别这么写。","id":"exc_94d5ec"},{"g":"exc","c":"try:\n    1 / 0\nexcept (ValueError, ZeroDivisionError) as e:\n    print(type(e).__name__)","a":"ZeroDivisionError","d":["ValueError","什么都不输出"],"w":"元组可以一次捕获多种异常。","id":"exc_ea3ebb"},{"g":"exc","c":"try:\n    {}['k']\nexcept LookupError:\n    print('caught')","a":"caught","d":["KeyError","什么都不输出"],"w":"KeyError 和 IndexError 都是 LookupError 的子类。","id":"exc_6d98b1"},{"g":"exc","c":"try:\n    raise ValueError('boom')\nexcept ValueError as e:\n    print(e, e.args)","a":"boom ('boom',)","d":["ValueError boom","boom boom"],"w":"异常对象带着你传进去的消息。","id":"exc_8fe7c3"},{"g":"exc","c":"try:\n    int('x')\nexcept Exception:\n    print('A')\nexcept ValueError:\n    print('B')","a":"A","d":["B","A ⏎ B"],"w":"except 从上往下匹配,宽的写前面会把窄的挡住。","id":"exc_4eae63"},{"g":"exc","c":"assert 1 == 2, 'no'","a":"AssertionError","d":["什么都不输出","ValueError"],"w":"assert 条件为假就抛错;只用于自检,不用于校验输入。","id":"exc_ff7ae8"},{"g":"exc","c":"class MyErr(Exception):\n    pass\ntry:\n    raise MyErr('x')\nexcept Exception as e:\n    print(type(e).__name__)","a":"MyErr","d":["Exception","x"],"w":"自定义异常继承 Exception 即可。","id":"exc_786485"},{"g":"exc","c":"x = None\nx.strip()","a":"AttributeError","d":["TypeError","None"],"w":"对 None 调方法——最常见的线上报错之一。","id":"exc_f22b7b"},{"g":"exc","c":"from contextlib import suppress\nwith suppress(KeyError):\n    {}['a']\nprint('ok')","a":"ok","d":["KeyError","什么都不输出"],"w":"suppress 是\"这种错我知道,忽略\"的简洁写法。","id":"exc_a1042b"},{"g":"exc","c":"def parse(s):\n    try:\n        return int(s)\n    except ValueError:\n        return None\nprint(parse('7'), parse('x'))","a":"7 None","d":["7 ValueError","7 0"],"w":"把\"可能失败\"收在函数里,调用方只看结果。","id":"exc_e2a99d"},{"g":"exc","c":"try:\n    [][0]\nexcept KeyError:\n    print('K')\nexcept IndexError:\n    print('I')","a":"I","d":["K","IndexError"],"w":"列表越界是 IndexError,不是 KeyError。","id":"exc_c82ca1"},{"g":"exc","c":"try:\n    raise ValueError('a')\nexcept ValueError as e:\n    msg = str(e)\nprint(msg)","a":"a","d":["ValueError('a')","NameError"],"w":"str(e) 拿消息文本。","id":"exc_c23f49"},{"g":"exc","c":"try:\n    pass\nexcept Exception:\n    pass\nprint(int(None))","a":"TypeError","d":["0","ValueError"],"w":"int(None) 是类型不对;int('x') 才是值不对。","id":"exc_97b865"},{"g":"io","c":"import json\nprint(json.dumps({'a': [1, None, True]}))","a":"{\"a\": [1, null, true]}","d":["{'a': [1, None, True]}","{\"a\": [1, None, True]}"],"w":"JSON 用双引号、null、true。","id":"io_4c3067"},{"g":"io","c":"import json\nprint(json.loads('{\"a\": 1.0}')['a'] + 1)","a":"2.0","d":["2","TypeError"],"w":"JSON 里的 1.0 读回来是 float。","id":"io_196892"},{"g":"io","c":"import json\njson.loads(\"{'a': 1}\")","a":"JSONDecodeError","d":["{'a': 1}","KeyError"],"w":"JSON 不认单引号。","id":"io_6faa1b"},{"g":"io","c":"import json\nprint(len(json.dumps('你')), len(json.dumps('你', ensure_ascii=False)))","a":"8 3","d":["3 3","8 8"],"w":"默认把中文转成 \\uXXXX;ensure_ascii=False 保留原字。","id":"io_3eeea6"},{"g":"io","c":"from pathlib import Path\np = Path('data/run1/log.txt')\nprint(p.name, p.suffix, p.stem, p.parent.name)","a":"log.txt .txt log run1","d":["log.txt txt log data","log .txt log.txt run1"],"w":"Path 把路径拆成有名字的零件。","id":"io_e0cdb0"},{"g":"io","c":"from pathlib import Path\nprint(Path('a') / 'b' / 'c.txt')","a":"a/b/c.txt","d":["a b c.txt","TypeError"],"w":"Path 用 / 拼路径。","id":"io_cb3d80"},{"g":"io","c":"import tempfile, os\np = os.path.join(tempfile.mkdtemp(), 'f.txt')\nwith open(p, 'w') as f:\n    f.write('a\\nb\\n')\nprint(open(p).read().splitlines())","a":"['a', 'b']","d":["['a\\n', 'b\\n']","['a', 'b', '']"],"w":"splitlines 去掉行尾换行,也不会多出空串。","id":"io_1dab1c"},{"g":"io","c":"import tempfile, os\np = os.path.join(tempfile.mkdtemp(), 'f.txt')\nwith open(p, 'w') as f:\n    f.write('a\\nb\\n')\nwith open(p) as f:\n    print([len(line) for line in f])","a":"[2, 2]","d":["[1, 1]","[4]"],"w":"逐行读时每行都带着末尾的换行符。","id":"io_20c4bf"},{"g":"io","c":"import tempfile, os\np = os.path.join(tempfile.mkdtemp(), 'f.txt')\nopen(p, 'w').write('a')\nopen(p, 'a').write('b')\nopen(p, 'w').write('c')\nprint(open(p).read())","a":"c","d":["abc","ab"],"w":"'w' 打开即清空;'a' 才是追加。","id":"io_acecdd"},{"g":"io","c":"open('/no/such/file.txt')","a":"FileNotFoundError","d":["None","OSError"],"w":"读不存在的文件。","id":"io_a47290"},{"g":"io","c":"import json\nprint(json.loads(json.dumps({1: 'a'})))","a":"{'1': 'a'}","d":["{1: 'a'}","TypeError"],"w":"JSON 的键只能是字符串,数字键来回一趟就变了。","id":"io_f7561b"},{"g":"io","c":"import json\njson.dumps({'s': {1, 2}})","a":"TypeError","d":["{\"s\": [1, 2]}","ValueError"],"w":"集合不能直接序列化成 JSON,先转 list。","id":"io_9980a1"},{"g":"io","c":"import csv, io\nr = csv.DictReader(io.StringIO('a,b\\n1,2\\n'))\nprint(next(r))","a":"{'a': '1', 'b': '2'}","d":["{'a': 1, 'b': 2}","['1', '2']"],"w":"csv 读出来全是字符串,数字要自己转。","id":"io_f076cd"},{"g":"io","c":"import tempfile, os\np = os.path.join(tempfile.mkdtemp(), 'f.txt')\nwith open(p, 'w') as f:\n    pass\nprint(f.closed)","a":"True","d":["False","NameError"],"w":"离开 with 块,文件自动关闭。","id":"io_5de82d"},{"g":"io","c":"import json\ntext = '{\"n\": 1}\\n{\"n\": 2}'\nprint([json.loads(l)['n'] for l in text.splitlines()])","a":"[1, 2]","d":["[{'n': 1}, {'n': 2}]","JSONDecodeError"],"w":"JSONL:一行一个 JSON,逐行解析。","id":"io_b4c76b"},{"g":"io","c":"from pathlib import Path\nprint(Path('/definitely/not/here').exists())","a":"False","d":["FileNotFoundError","None"],"w":"exists() 只回答有没有,不抛错。","id":"io_b0cb68"},{"g":"io","c":"import os\nprint(os.path.splitext('a.tar.gz'))","a":"('a.tar', '.gz')","d":["('a', '.tar.gz')","['a', 'tar', 'gz']"],"w":"只切最后一个扩展名。","id":"io_e2d19d"},{"g":"io","c":"import json\nprint(json.dumps({'b': 1, 'a': 2}, sort_keys=True))","a":"{\"a\": 2, \"b\": 1}","d":["{\"b\": 1, \"a\": 2}","{'a': 2, 'b': 1}"],"w":"sort_keys 让输出稳定,方便比对和做哈希。","id":"io_cb9a8c"},{"g":"std","c":"from collections import Counter\nc = Counter(['a', 'b', 'a'])\nprint(c['a'], c['z'])","a":"2 0","d":["2 KeyError","2 None"],"w":"Counter 没见过的键返回 0。","id":"std_267889"},{"g":"std","c":"from collections import deque\nd = deque([1, 2, 3], maxlen=2)\nprint(list(d))","a":"[2, 3]","d":["[1, 2]","[1, 2, 3]"],"w":"定长队列:满了自动挤掉最旧的。","id":"std_78fc21"},{"g":"std","c":"import itertools\nprint(list(itertools.chain([1], [2, 3])))","a":"[1, 2, 3]","d":["[[1], [2, 3]]","[1, [2, 3]]"],"w":"chain 把多个可迭代对象首尾相接。","id":"std_0a17a9"},{"g":"std","c":"import itertools\nprint(len(list(itertools.combinations('abc', 2))), len(list(itertools.permutations('abc', 2))))","a":"3 6","d":["6 6","3 3"],"w":"组合不看顺序,排列看顺序。","id":"std_4eebae"},{"g":"std","c":"from datetime import date, timedelta\nprint(date(2026, 11, 10) + timedelta(days=30))","a":"2026-12-10","d":["2026-11-40","2026-12-11"],"w":"日期加减用 timedelta,自动进位。","id":"std_7c08f3"},{"g":"std","c":"from datetime import date\nprint((date(2026, 3, 1) - date(2026, 2, 1)).days)","a":"28","d":["30","1"],"w":"两个日期相减得到 timedelta。","id":"std_f97764"},{"g":"std","c":"from datetime import datetime\nprint(datetime.strptime('2026-11-10', '%Y-%m-%d').weekday())","a":"1","d":["2","10"],"w":"weekday():周一是 0,所以周二是 1。","id":"std_c4bde2"},{"g":"std","c":"from datetime import date\nprint(date(2026, 1, 5).strftime('%m/%d/%y'))","a":"01/05/26","d":["1/5/2026","05/01/26"],"w":"strftime 把日期格式化成文本;strptime 反过来。","id":"std_03a8a2"},{"g":"std","c":"import random\nrandom.seed(0)\na = random.random()\nrandom.seed(0)\nprint(a == random.random())","a":"True","d":["False"],"w":"固定种子,随机序列可复现——实验可重复的前提。","id":"std_7459fd"},{"g":"std","c":"import math\nprint(math.floor(-1.5), math.ceil(1.2), math.sqrt(16))","a":"-2 2 4.0","d":["-1 2 4","-2 1 4.0"],"w":"floor 往下,ceil 往上;sqrt 返回 float。","id":"std_b3856d"},{"g":"std","c":"import re\nprint(re.findall(r'\\d+', 'a12b3'))","a":"['12', '3']","d":["['1', '2', '3']","['a', 'b']"],"w":"\\d+ 匹配连续的数字。","id":"std_1cbd74"},{"g":"std","c":"import re\nprint(bool(re.match('b', 'abc')), bool(re.search('b', 'abc')))","a":"False True","d":["True True","False False"],"w":"match 只从开头匹配;search 找任意位置。","id":"std_7131f4"},{"g":"std","c":"import re\nprint(re.sub(r'(\\w+)@(\\w+)', r'\\2:\\1', 'me@host'))","a":"host:me","d":["me:host","\\2:\\1"],"w":"\\1 \\2 引用括号捕获到的分组。","id":"std_b29159"},{"g":"std","c":"from functools import lru_cache\nn = 0\n@lru_cache\ndef f(x):\n    global n\n    n += 1\n    return x\nf(1); f(1); f(2)\nprint(n)","a":"2","d":["3","1"],"w":"相同参数第二次直接走缓存,函数体不再执行。","id":"std_762474"},{"g":"std","c":"import heapq\nprint(heapq.nsmallest(2, [5, 1, 4, 2]))","a":"[1, 2]","d":["[5, 1]","[2, 1]"],"w":"取前 N 小/大,不用整个排序。","id":"std_265f7d"},{"g":"std","c":"import statistics\nprint(statistics.mean([1, 2, 3, 6]), statistics.median([1, 2, 3, 6]))","a":"3 2.5","d":["3.0 3","3 2"],"w":"均值受极端值拉动,中位数不会。","id":"std_e11979"},{"g":"std","c":"import hashlib\nprint(len(hashlib.sha256(b'x').hexdigest()))","a":"64","d":["256","32"],"w":"sha256 是 256 位,十六进制写出来 64 个字符。","id":"std_f4cd72"},{"g":"std","c":"from decimal import Decimal\nprint(Decimal('0.1') + Decimal('0.2') == Decimal('0.3'))","a":"True","d":["False"],"w":"金额计算用 Decimal,且从字符串构造。","id":"std_bd70f9"},{"g":"std","c":"import itertools\nprint([k for k, _ in itertools.groupby('aabba')])","a":"['a', 'b', 'a']","d":["['a', 'b']","['aa', 'bb', 'a']"],"w":"groupby 只合并相邻的;要全局分组得先排序。","id":"std_630121"},{"g":"std","c":"import bisect\nprint(bisect.bisect_left([1, 3, 5], 3), bisect.bisect_left([1, 3, 5], 4))","a":"1 2","d":["1 1","2 2"],"w":"在有序列表里二分找插入位置。","id":"std_47b57d"},{"g":"std","c":"import itertools\nprint(list(itertools.islice(itertools.count(5), 3)))","a":"[5, 6, 7]","d":["[5, 6, 7, 8]","[0, 1, 2]"],"w":"count 是无限序列,islice 切一段出来。","id":"std_e8b402"},{"g":"std","c":"from functools import partial\np = partial(pow, 2)\nprint(p(5))","a":"32","d":["25","10"],"w":"partial 先钉住一部分参数:pow(2, 5)。","id":"std_ce0878"},{"g":"std","c":"import itertools\nprint(list(itertools.accumulate([1, 2, 3])))","a":"[1, 3, 6]","d":["[6]","[1, 2, 3]"],"w":"累计和;算净值曲线、累计收益的原型。","id":"std_98e219"},{"g":"std","c":"from collections import OrderedDict, namedtuple\nP = namedtuple('P', 'x y')\nprint(P(1, 2).x + P(1, 2)[1])","a":"3","d":["TypeError","12"],"w":"namedtuple:带字段名的轻量元组。","id":"std_6d494a"},{"g":"std","c":"import time\nt0 = time.perf_counter()\ndt = time.perf_counter() - t0\nprint(dt >= 0, type(dt).__name__)","a":"True float","d":["False float","True int"],"w":"perf_counter 单调递增,专门用来量间隔。","id":"std_719a47"},{"g":"flow","c":"def g():\n    yield 1\n    yield 2\nx = g()\nprint(next(x), list(x))","a":"1 [2]","d":["1 [1, 2]","[1, 2] []"],"w":"生成器记得自己走到哪了。","id":"flow_ef953a"},{"g":"flow","c":"def g():\n    print('start', end=' ')\n    yield 1\nx = g()\nprint('made', end=' ')\nnext(x)","a":"made start","d":["start made","made"],"w":"调用生成器函数不执行函数体,第一次 next 才开始。","id":"flow_d0edad"},{"g":"flow","c":"it = iter([])\nnext(it)","a":"StopIteration","d":["None","IndexError"],"w":"迭代器走完再 next 就抛 StopIteration。","id":"flow_aa686c"},{"g":"flow","c":"print(next(iter([]), 'none'))","a":"none","d":["StopIteration","None"],"w":"next 的第二个参数是走完时的默认值。","id":"flow_e39ef5"},{"g":"flow","c":"def twice(f):\n    def w(*a):\n        return f(*a) * 2\n    return w\n@twice\ndef one():\n    return 1\nprint(one())","a":"2","d":["1","11"],"w":"装饰器:拿函数进去,换一个包装过的出来。","id":"flow_aa99fb"},{"g":"flow","c":"def twice(f):\n    def w(*a):\n        return f(*a) * 2\n    return w\n@twice\ndef one():\n    return 1\nprint(one.__name__)","a":"w","d":["one","twice"],"w":"名字被包装函数顶替了;用 functools.wraps 保住原名。","id":"flow_4c56e5"},{"g":"flow","c":"class C:\n    def __enter__(self):\n        print('in', end=' ')\n        return 5\n    def __exit__(self, *a):\n        print('out', end=' ')\nwith C() as v:\n    print(v, end=' ')","a":"in 5 out","d":["5 in out","in out 5"],"w":"as 拿到的是 __enter__ 的返回值;离开时调 __exit__。","id":"flow_697355"},{"g":"flow","c":"from contextlib import contextmanager\n@contextmanager\ndef tag():\n    print('\u003c', end='')\n    yield\n    print('>', end='')\nwith tag():\n    print('x', end='')","a":"\u003cx>","d":["x\u003c>","\u003c>x"],"w":"yield 之前是进入,之后是退出。","id":"flow_8d25e4"},{"g":"flow","c":"def g():\n    yield from [1, 2]\n    yield 3\nprint(list(g()))","a":"[1, 2, 3]","d":["[[1, 2], 3]","[3]"],"w":"yield from 把另一个可迭代对象逐个转交出去。","id":"flow_5c1090"},{"g":"flow","c":"print(hasattr([], '__iter__'), hasattr(5, '__iter__'))","a":"True False","d":["True True","False False"],"w":"能不能 for,看有没有 __iter__。","id":"flow_6b02ea"},{"g":"flow","c":"e = enumerate('ab')\nlist(e)\nprint(list(e))","a":"[]","d":["[(0, 'a'), (1, 'b')]","TypeError"],"w":"enumerate、zip、map 返回的都是一次性迭代器。","id":"flow_2b97ba"},{"g":"flow","c":"d = {'a': 1}\nk = d.keys()\nd['b'] = 2\nprint(len(k))","a":"2","d":["1","RuntimeError"],"w":"keys() 是活的视图,跟着字典变。","id":"flow_6c5af7"},{"g":"flow","c":"import functools\ndef deco(f):\n    @functools.wraps(f)\n    def w(*a, **k):\n        return f(*a, **k)\n    return w\n@deco\ndef hello():\n    return 'hi'\nprint(hello.__name__, hello())","a":"hello hi","d":["w hi","deco hi"],"w":"wraps 把原函数的名字和文档抄到包装函数上。","id":"flow_142f2e"},{"g":"flow","c":"def countdown(n):\n    while n > 0:\n        yield n\n        n -= 1\nprint(sum(countdown(4)))","a":"10","d":["4","6"],"w":"4+3+2+1;生成器按需产出,不占列表的内存。","id":"flow_6ecc07"},{"g":"mod","c":"import asyncio\nasync def f():\n    return 7\nprint(asyncio.run(f()))","a":"7","d":["\u003ccoroutine>","None"],"w":"asyncio.run 启动事件循环并跑完协程。","id":"mod_18557e"},{"g":"mod","c":"import asyncio\nasync def w(n, d):\n    await asyncio.sleep(d)\n    return n\nasync def main():\n    return await asyncio.gather(w('a', .02), w('b', .01))\nprint(asyncio.run(main()))","a":"['a', 'b']","d":["['b', 'a']","('a', 'b')"],"w":"gather 的结果按传入顺序,不按完成先后。","id":"mod_c58742"},{"g":"mod","c":"import asyncio, time\nasync def main():\n    t = time.perf_counter()\n    await asyncio.gather(asyncio.sleep(.05), asyncio.sleep(.05))\n    return time.perf_counter() - t \u003c .09\nprint(asyncio.run(main()))","a":"True","d":["False"],"w":"两个等待并发进行,总耗时约等于最长的那个。","id":"mod_72748e"},{"g":"mod","c":"x: int = 'a'\nprint(type(x).__name__)","a":"str","d":["int","TypeError"],"w":"标注不会在运行时拦你;查类型靠 mypy/pyright。","id":"mod_a64544"},{"g":"mod","c":"from typing import Optional\ndef f(x: Optional[int] = None):\n    return x or -1\nprint(f(), f(0), f(5))","a":"-1 -1 5","d":["-1 0 5","None 0 5"],"w":"x or 默认值 会吞掉 0;应写 x if x is not None else -1。","id":"mod_d18bee"},{"g":"mod","c":"print(__name__)","a":"__main__","d":["None","__name__"],"w":"直接运行的脚本名字是 __main__,被 import 时是模块名。","id":"mod_f4d1a8"},{"g":"mod","c":"print({**{'a': 1}, 'a': 2})","a":"{'a': 2}","d":["{'a': 1}","SyntaxError"],"w":"** 展开字典,后写的覆盖先写的。","id":"mod_ec6331"},{"g":"mod","c":"print(*[1, 2, 3], sep='-')","a":"1-2-3","d":["[1, 2, 3]","1 2 3"],"w":"* 把列表拆成多个位置参数。","id":"mod_5a4203"},{"g":"mod","c":"from concurrent.futures import ThreadPoolExecutor\nwith ThreadPoolExecutor() as ex:\n    print(list(ex.map(lambda x: x * x, [1, 2, 3])))","a":"[1, 4, 9]","d":["[9, 4, 1]","14"],"w":"线程池的 map 结果保持输入顺序。","id":"mod_c44c76"},{"g":"mod","c":"def f(xs: list[int]) -> dict[str, int]:\n    return {'n': len(xs)}\nprint(f([1, 2]))","a":"{'n': 2}","d":["TypeError","{'n': [1, 2]}"],"w":"内置容器可以直接带方括号写标注。","id":"mod_6494f8"},{"g":"mod","c":"a = [1, 2, 3]\nfirst, *_, last = a\nprint(first, last)","a":"1 3","d":["1 2","1 [2, 3]"],"w":"用 _ 接住不关心的部分。","id":"mod_f8ee6e"},{"g":"mod","c":"def greet(name, *, loud=False):\n    return name.upper() if loud else name\nprint(greet('ada', loud=True))","a":"ADA","d":["ada","TypeError"],"w":"开关类参数强制写名字,调用处一眼看得懂。","id":"mod_652fab"},{"g":"mod","c":"import sys\nprint(type(sys.argv).__name__, sys.version_info >= (3, 10))","a":"list True","d":["tuple True","str False"],"w":"命令行参数在 sys.argv 里,是字符串列表。","id":"mod_7ff1a6"},{"g":"mod","c":"nums = [3, 1, 2]\nprint(f'{max(nums)=}', f'{len(nums):>3}|')","a":"max(nums)=3   3|","d":["max(nums)=3 3|","3   3|"],"w":"f-string 里可以放任意表达式和对齐格式。","id":"mod_7ce041"},{"g":"np","c":"import numpy as np\na = np.array([1, 2, 3])\nprint((a * 2).tolist(), [1, 2, 3] * 2)","a":"[2, 4, 6] [1, 2, 3, 1, 2, 3]","d":["[2, 4, 6] [2, 4, 6]","[1, 2, 3, 1, 2, 3] [1, 2, 3, 1, 2, 3]"],"w":"数组乘法是逐元素;列表乘法是重复。","id":"np_ce1bdb"},{"g":"np","c":"import numpy as np\na = np.arange(6).reshape(2, 3)\nprint(a.shape, a.sum(axis=0).tolist())","a":"(2, 3) [3, 5, 7]","d":["(2, 3) [3, 12]","(3, 2) [3, 5, 7]"],"w":"axis=0 沿着行方向压扁,得到每列的和。","id":"np_8c281d"},{"g":"np","c":"import numpy as np\na = np.arange(6).reshape(2, 3)\nprint(a.sum(axis=1).tolist())","a":"[3, 12]","d":["[3, 5, 7]","15"],"w":"axis=1 压掉列,得到每行的和。","id":"np_80d832"},{"g":"np","c":"import numpy as np\na = np.array([1, 5, 3])\nprint(a[a > 2].tolist())","a":"[5, 3]","d":["[False, True, True]","[1]"],"w":"布尔数组当下标,就是筛选。","id":"np_70015f"},{"g":"np","c":"import numpy as np\na = np.arange(4)\nb = a[:2]\nb[0] = 9\nprint(a.tolist())","a":"[9, 1, 2, 3]","d":["[0, 1, 2, 3]","[9, 1]"],"w":"NumPy 切片是视图不是副本;要副本用 .copy()。","id":"np_ed1bda"},{"g":"np","c":"import numpy as np\nprint(np.array([1, 2]).dtype, np.array([1, 2.0]).dtype)","a":"int64 float64","d":["int64 int64","float64 float64"],"w":"数组只有一种类型,混了就向上提升。","id":"np_d98448"},{"g":"np","c":"import numpy as np\nprint((np.array([[1], [2]]) + np.array([10, 20])).tolist())","a":"[[11, 21], [12, 22]]","d":["[[11], [22]]","ValueError"],"w":"广播:形状 (2,1) 和 (2,) 自动撑成 (2,2)。","id":"np_968eb9"},{"g":"np","c":"import numpy as np\nprint(np.mean([1, 2, 3, 4]), np.array([1, 9, 3]).argmax())","a":"2.5 1","d":["2.5 9","2 1"],"w":"argmax 给的是位置,不是值。","id":"np_765906"},{"g":"np","c":"import numpy as np\nprint(np.nan == np.nan, np.isnan(np.nan))","a":"False True","d":["True True","False False"],"w":"NaN 不等于任何东西,包括它自己;用 isnan 判断。","id":"np_56c203"},{"g":"np","c":"import numpy as np\np = np.array([100., 110., 121.])\nprint(np.round(p[1:] / p[:-1] - 1, 2).tolist())","a":"[0.1, 0.1]","d":["[10.0, 11.0]","[0.1, 0.1, 0.1]"],"w":"错位相除减一:收益率的最短写法。","id":"np_41064f"},{"g":"np","c":"import numpy as np\nprint(np.where(np.array([1, -2, 3]) > 0, 1, 0).tolist())","a":"[1, 0, 1]","d":["[0, 2]","[1, -2, 3]"],"w":"where(条件, 真时取, 假时取):向量化的 if/else。","id":"np_fc8a9f"},{"g":"np","c":"import numpy as np\nprint(np.cumsum([1, 2, 3]).tolist(), np.linspace(0, 1, 5).tolist())","a":"[1, 3, 6] [0.0, 0.25, 0.5, 0.75, 1.0]","d":["[6] [0.0, 0.2, 0.4, 0.6, 0.8]","[1, 3, 6] [0.0, 0.25, 0.5, 0.75]"],"w":"linspace 含两端,指定的是点数。","id":"np_6200f8"},{"g":"np","c":"import numpy as np\na = np.array([[1, 2], [3, 4]])\nprint(a.T.tolist(), a[:, 0].tolist())","a":"[[1, 3], [2, 4]] [1, 3]","d":["[[1, 2], [3, 4]] [1, 2]","[[1, 3], [2, 4]] [1, 2]"],"w":".T 转置;[:, 0] 取第一列。","id":"np_e9b070"},{"g":"np","c":"import numpy as np\na = np.array([1, 2, 3])\nprint(a.mean(), a.std().round(3))","a":"2.0 0.816","d":["2.0 1.0","2 0.816"],"w":"NumPy 的 std 默认是总体标准差(ddof=0)。","id":"np_293e52"},{"g":"pd","c":"import pandas as pd\ns = pd.Series([1, 2, 3])\nprint(s.mean(), s.shift(1).isna().sum())","a":"2.0 1","d":["2.0 0","2 1"],"w":"shift(1) 整体下移一格,第一格变成 NaN。","id":"pd_2233da"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [1, 2, 3], 'b': [4, 5, 6]})\nprint(df.shape, df['a'].sum())","a":"(3, 2) 6","d":["(2, 3) 6","(3, 2) 15"],"w":"shape 是(行, 列)。","id":"pd_2752cb"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [1, 2, 3], 'b': [4, 5, 6]})\nprint(df[df.a > 1]['b'].tolist())","a":"[5, 6]","d":["[4, 5, 6]","[2, 3]"],"w":"布尔条件筛行,再取列。","id":"pd_ab2484"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [1, 2, 3], 'b': [4, 5, 6]})\nprint(df.loc[0, 'b'], df.iloc[-1, 0])","a":"4 3","d":["4 6","1 3"],"w":"loc 按标签,iloc 按位置。","id":"pd_87749b"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'k': ['x', 'y', 'x'], 'v': [1, 2, 3]})\nprint(df.groupby('k')['v'].sum().to_dict())","a":"{'x': 4, 'y': 2}","d":["{'x': 1, 'y': 2}","{'x': 3, 'y': 2}"],"w":"groupby:分组、取列、聚合。","id":"pd_908bd6"},{"g":"pd","c":"import pandas as pd\nprint(pd.Series([100, 110, 121]).pct_change().round(2).tolist())","a":"[nan, 0.1, 0.1]","d":["[0.1, 0.1]","[0.0, 0.1, 0.1]"],"w":"第一个没有前值,是 NaN。","id":"pd_a13200"},{"g":"pd","c":"import pandas as pd\nprint(pd.Series([1, 2, 3, 4]).rolling(2).mean().tolist())","a":"[nan, 1.5, 2.5, 3.5]","d":["[1.5, 2.5, 3.5]","[1.0, 1.5, 2.5, 3.5]"],"w":"窗口没凑满时给 NaN。","id":"pd_99a85e"},{"g":"pd","c":"import pandas as pd\ns = pd.Series([1, None, 3])\nprint(len(s.dropna()), s.fillna(0).sum())","a":"2 4.0","d":["3 4.0","2 4"],"w":"dropna 丢掉缺失;fillna 补上。有过缺失的列是 float。","id":"pd_44c1f2"},{"g":"pd","c":"import pandas as pd\na = pd.DataFrame({'k': [1, 2]})\nb = pd.DataFrame({'k': [2, 3]})\nprint(len(a.merge(b)), len(a.merge(b, how='outer')))","a":"1 3","d":["2 3","1 4"],"w":"默认内连接只留两边都有的键。","id":"pd_381bdb"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'k': ['x', 'y', 'z'], 'v': [2, 3, 1]})\nprint(df.sort_values('v', ascending=False)['k'].tolist())","a":"['y', 'x', 'z']","d":["['z', 'x', 'y']","['x', 'y', 'z']"],"w":"按某列排序;ascending=False 倒序。","id":"pd_14a212"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [1, 2, 3], 'b': [4, 5, 6]})\ndf['c'] = df.a * df.b\nprint(df.c.tolist())","a":"[4, 10, 18]","d":["[32]","[5, 7, 9]"],"w":"列与列逐行运算,直接赋成新列。","id":"pd_bf604a"},{"g":"pd","c":"import pandas as pd\nprint(pd.Series(list('aab')).value_counts().to_dict())","a":"{'a': 2, 'b': 1}","d":["{'a': 1, 'b': 1}","['a', 'b']"],"w":"value_counts:每个值出现几次,从多到少。","id":"pd_c0070a"},{"g":"pd","c":"import pandas as pd\nprint((1 + pd.Series([.1, .1])).cumprod().round(2).tolist())","a":"[1.1, 1.21]","d":["[1.1, 1.2]","[0.1, 0.01]"],"w":"(1+收益率) 连乘就是净值曲线。","id":"pd_29c13b"},{"g":"pd","c":"import pandas as pd\nprint(pd.to_datetime('2026-11-10').day_name())","a":"Tuesday","d":["Monday","10"],"w":"to_datetime 把文本变成时间戳,之后能做日期运算。","id":"pd_ec0824"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [1, 2, 3]})\nsub = df[df.a > 1].copy()\nsub['a'] = 0\nprint(df.a.tolist())","a":"[1, 2, 3]","d":["[1, 0, 0]","[0, 0, 0]"],"w":"筛出来要改就先 .copy(),原表不受影响。","id":"pd_4ced5d"},{"g":"pd","c":"import pandas as pd\ndf = pd.DataFrame({'a': [3, 1, 2]})\nprint(df.a.rank().tolist(), df.a.idxmax())","a":"[3.0, 1.0, 2.0] 0","d":["[1.0, 2.0, 3.0] 0","[3.0, 1.0, 2.0] 3"],"w":"rank 给名次;idxmax 给最大值所在的行标签。","id":"pd_2b69e6"}];
